const preference=matchMedia('(prefers-reduced-motion: reduce)');let effectsPaused=preference.matches;
const background=document.querySelector('.ambient-background'),effectsButton=document.querySelector('#effects-control');
function applyEffects(){document.body.classList.toggle('effects-paused',effectsPaused);effectsButton.setAttribute('aria-pressed',String(effectsPaused));effectsButton.querySelector('.effects-label').textContent=effectsPaused?'Play effects':'Pause effects';window.dispatchEvent(new CustomEvent('portfolio-motion',{detail:{paused:effectsPaused}}))}
effectsButton.addEventListener('click',()=>{effectsPaused=!effectsPaused;applyEffects()});preference.addEventListener('change',e=>{if(e.matches){effectsPaused=true;applyEffects()}});applyEffects();
const canvas=document.querySelector('#ambient-canvas'),ctx=canvas.getContext('2d');let width=innerWidth,height=innerHeight,dpr=1,pointer={x:.5,y:.35},smooth={x:.5,y:.35};
function resize(){width=innerWidth;height=innerHeight;dpr=Math.min(devicePixelRatio,1.5);canvas.width=width*dpr;canvas.height=height*dpr;ctx?.setTransform(dpr,0,0,dpr,0,0)}resize();window.addEventListener('resize',resize,{passive:true});
if(matchMedia('(pointer: fine)').matches)window.addEventListener('pointermove',e=>{pointer.x=e.clientX/width;pointer.y=e.clientY/height},{passive:true});
let time=0,previous=0,lastDraw=0,scrollTarget=0,scrollPosition=0;window.addEventListener('scroll',()=>scrollTarget=scrollY*.00014,{passive:true});
const count=innerWidth<760?18:42;const seeds=Array.from({length:count},(_,i)=>({x:Math.sin(i*19.713)*3.3,y:Math.cos(i*9.73)*2.5,z:(i/count)*5-2.5,size:.5+(i%4)*.18}));
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-previous)/1000,.06);previous=now;if(document.hidden||now-lastDraw<32||!ctx)return;lastDraw=now;if(!effectsPaused){time+=dt;smooth.x+=(pointer.x-smooth.x)*.055;smooth.y+=(pointer.y-smooth.y)*.055;scrollPosition+=(scrollTarget-scrollPosition)*.04}background.style.setProperty('--pointer-x',`${smooth.x*100}%`);background.style.setProperty('--pointer-y',`${smooth.y*100}%`);ctx.clearRect(0,0,width,height);const ax=(smooth.x-.5)*.18+time*.018,ay=(smooth.y-.5)*.1;const sx=Math.sin(ax),cx=Math.cos(ax),scale=Math.min(width,height)*.42;const projected=seeds.map((p,i)=>{const x=p.x*cx-p.z*sx,z=p.x*sx+p.z*cx;const y=p.y+Math.sin(time*.22+i)*.06-scrollPosition;const perspective=4.8/(6.5+z);return{x:width*.5+(x+(smooth.x-.5)*.2)*scale*perspective,y:height*.5+(y+ay)*scale*perspective,size:p.size*perspective,alpha:.16+perspective*.15+Math.sin(time*1.1+i)*.06}});
projected.forEach((p,i)=>{if(p.x<0||p.x>width||p.y<0||p.y>height)return;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fillStyle=i%5===0?`rgba(210,194,255,${p.alpha})`:i%7===0?`rgba(231,170,207,${p.alpha})`:`rgba(222,159,207,${p.alpha})`;ctx.fill();for(let j=i+1;j<projected.length;j++){const q=projected[j],dist=Math.hypot(p.x-q.x,p.y-q.y);if(dist<105){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=`rgba(222,159,207,${(1-dist/105)*.055})`;ctx.lineWidth=.6;ctx.stroke()}}const mouseDist=Math.hypot(p.x-smooth.x*width,p.y-smooth.y*height);if(mouseDist<150&&!effectsPaused){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(smooth.x*width,smooth.y*height);ctx.strokeStyle=`rgba(222,159,207,${(1-mouseDist/150)*.09})`;ctx.stroke()}});
}requestAnimationFrame(frame);
if(!preference.matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('reveal-pending');e.target.classList.add('reveal-visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.builds-heading,.about-copy,.education-grid,.timeline article,.service-grid article').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('reveal-ready','reveal-pending');observer.observe(el)}});window.addEventListener('portfolio-motion',e=>{if(e.detail.paused){document.querySelectorAll('.reveal-pending').forEach(el=>{el.classList.remove('reveal-pending');el.classList.add('reveal-visible');observer.unobserve(el)})}})}
